347: bool isOperatingSystemInDarkMode()
348: {
349: #if QT_VERSION >= QT_VERSION_CHECK(6, 5, 0)
350:     // Qt 6.5+ has native cross-platform API
351:     return QGuiApplication::styleHints()->colorScheme() == Qt::ColorScheme::Dark;
352: #elif defined(Q_OS_WIN32)
353:     // Windows: Read registry AppsUseLightTheme
354:     // DWORD value 0 = dark mode, 1 = light mode
355:     // Registry path: HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize
356:     QSettings settings(
357:         "HKEY_CURRENT_USER\\Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\Personalize",
358:         QSettings::NativeFormat);
359:     bool ok = false;
360:     int value = settings.value("AppsUseLightTheme", 1).toInt(&ok);
361:     return (ok && value == 0);
362: #elif defined(Q_OS_MACOS)
363:     // macOS: Run 'defaults read -g AppleInterfaceStyle'
364:     // Returns "Dark" if dark mode is active, empty otherwise
365:     QProcess process;
366:     process.start("/usr/bin/defaults", QStringList() << "read" << "-g" << "AppleInterfaceStyle");
367:     process.waitForFinished(3000);
368:     QString output = QString::fromUtf8(process.readAllStandardOutput()).trimmed();
369:     return output.contains("Dark", Qt::CaseInsensitive);
370: #elif defined(Q_OS_LINUX)
371:     // Linux: Try gsettings for GNOME 42+
372:     // Returns "dark" or "prefer-dark" in dark mode
373:     QProcess process;
374:     process.start("gsettings", QStringList() << "get" << "org.gnome.desktop.interface" << "color-scheme");
375:     process.waitForFinished(3000);
376:     QString output = QString::fromUtf8(process.readAllStandardOutput()).trimmed();
377:     return output.contains("dark", Qt::CaseInsensitive);
378: #else
379:     // Unknown platform or headless: assume light mode
380:     return false;
381: #endif
